const MAX_VISIBLE_TAGS = 50;

const TAG_MESSAGES = {
  empty: "Tags list not available",
  error: "Unable to load tags",
  loading: "Loading tags...",
};

export { MAX_VISIBLE_TAGS, TAG_MESSAGES };

import { useEffect, useState } from "react";
import getTags from "../../services/getTags";

const TAG_STATUS = {
  IDLE: "idle",
  LOADING: "loading",
  SUCCESS: "success",
  ERROR: "error",
};

function usePopularTags() {
  const [tags, setTags] = useState([]);
  const [status, setStatus] = useState(TAG_STATUS.IDLE);

  useEffect(() => {
    let isMounted = true;

    setStatus(TAG_STATUS.LOADING);

    getTags()
      .then((tagsList) => {
        if (!isMounted) return;

        setTags(tagsList);
        setStatus(TAG_STATUS.SUCCESS);
      })
      .catch((error) => {
        if (!isMounted) return;

        console.error(error);
        setStatus(TAG_STATUS.ERROR);
      });

    return () => {
      isMounted = false;
    };
  }, []);

  return { status, tags };
}

export { TAG_STATUS };
export default usePopularTags;

